protected override void EncodeSignature(Signature? signature, RlpStream stream, bool forSigning, bool isEip155Enabled, ulong chainId)
{
    if (forSigning)
    {
        if (IncludeSigChainIdHack(isEip155Enabled, chainId))
        {
            stream.Encode(chainId);
            stream.Encode(Rlp.OfEmptyByteArray);  // 0
            stream.Encode(Rlp.OfEmptyByteArray);  // 0
        }
    }
    else
    {
        base.EncodeSignature(signature, stream, false, isEip155Enabled, chainId);
    }
}

private static bool IncludeSigChainIdHack(bool isEip155Enabled, ulong chainId) => isEip155Enabled && chainId != 0;

// PRIMARY: src/Nethermind/Nethermind.Crypto/EthereumEcdsaExtensions.cs:Sign (lines 24-38)
public static void Sign(this IEthereumEcdsa ecdsa, PrivateKey privateKey, Transaction tx, bool isEip155Enabled = true)
{
    if (tx.Type != TxType.Legacy)
    {
        tx.ChainId = ecdsa.ChainId;
    }
    ValueHash256 hash = ValueKeccak.Compute(Rlp.Encode(tx, true, isEip155Enabled, ecdsa.ChainId).Bytes);
    tx.Signature = ecdsa.Sign(privateKey, in hash);
    if (tx.Type == TxType.Legacy && isEip155Enabled)
    {
        tx.Signature.V = tx.Signature.V + 8 + 2 * ecdsa.ChainId;
    }
}

